def covered(segments):
    intervals = sorted((s, e) for s, e in segments if e > s)
    total = 0
    end = None
    for start, stop in intervals:
        if end is None or start > end:
            total += stop - start
            end = stop
        elif stop > end:
            total += stop - end
            end = stop
    return total

